import re
from datetime import datetime


def dedupe_contacts(rows):
    GMAIL_DOMAINS = ("gmail.com", "googlemail.com")
    OPT_OUT_VALUES = {"y", "yes", "true", "1"}
    EPOCH = datetime(1, 1, 1)

    def get(row, key):
        v = row.get(key, "")
        return "" if v is None else str(v)

    def norm_email(raw):
        s = raw
        m = re.search(r"<([^<>]*)>", s)
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if s.count("@") == 1:
            local, domain = s.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.replace(".", "").split("+")[0]
                domain = "gmail.com"
                s = local + "@" + domain
        # validity
        if s.count("@") != 1:
            return ""
        local, domain = s.split("@")
        if not local:
            return ""
        if "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return s

    def norm_phone(raw):
        s = raw
        m = re.search(r"ext|x|#", s, re.IGNORECASE)
        if m:
            s = s[:m.start()]
        digits = re.sub(r"[^0-9]", "", s)
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def norm_zip(raw):
        s = raw.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", s):
            s = s.split("-")[0]
        if re.fullmatch(r"[0-9]{4}", s):
            s = "0" + s
        if re.fullmatch(r"[0-9]{5}", s):
            return s
        return ""

    def norm_name(raw):
        s = raw.strip()
        if s.isupper() or s.islower():
            s = s.title()
        return s

    def parse_updated(raw):
        s = raw.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                continue
        raise ValueError("Unrecognized updated value: %r" % raw)

    def parse_tags(raw):
        out = set()
        for t in re.split(r"[;,]", raw):
            t = t.strip().lower()
            if t:
                out.add(t)
        return out

    # Normalize rows and drop those with neither a valid email nor a valid phone.
    recs = []
    for idx, row in enumerate(rows):
        email = norm_email(get(row, "email"))
        phone = norm_phone(get(row, "phone"))
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,
            "first_name": norm_name(get(row, "first_name")),
            "last_name": norm_name(get(row, "last_name")),
            "email": email,
            "phone": phone,
            "zip": norm_zip(get(row, "zip")),
            "source": get(row, "source").strip().lower(),
            "tags": parse_tags(get(row, "tags")),
            "opted_out": get(row, "opted_out").strip().lower() in OPT_OUT_VALUES,
            "updated": parse_updated(get(row, "updated")),
        })

    # Union-find over the kept records.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    seen_email = {}
    seen_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in seen_email:
                union(i, seen_email[r["email"]])
            else:
                seen_email[r["email"]] = i
        last = r["last_name"].lower()
        if r["phone"] and last:
            key = (r["phone"], last)
            if key in seen_phone_last:
                union(i, seen_phone_last[key])
            else:
                seen_phone_last[key] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    def pick(members, field):
        best = None
        best_key = None
        for i in members:
            r = recs[i]
            if not r[field]:
                continue
            key = (
                0 if r["source"] == "manual" else 1,
                -(r["updated"] - EPOCH).total_seconds(),
                r["idx"],
            )
            if best_key is None or key < best_key:
                best_key = key
                best = r[field]
        return best if best is not None else ""

    result = []
    # Groups ordered by earliest row in the input (members are in input order).
    for members in sorted(groups.values(), key=lambda m: recs[m[0]]["idx"]):
        tags = set()
        for i in members:
            tags |= recs[i]["tags"]
        latest = max(recs[i]["updated"] for i in members)
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": "%04d-%02d-%02d" % (latest.year, latest.month, latest.day),
        })
    return result
```

Notes for tomorrow's send:

- **Opted-out people are kept in the output**, flagged `opted_out == "Y"`, as the rules specify. Filter them out before sending, e.g. `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N"]`, and also skip anyone with an empty `email`.
- **Opt-outs are merged across duplicates.** If any row for a person says they opted out, the whole person is marked "Y".
- **Rows dropped by rule 9 are ignored entirely.** A row with no valid email or phone can't be matched, so an opt-out on such a row won't suppress anyone.
- **Phone-only matching** requires a non-empty last name on both rows, and transitive merging can chain people together through shared emails or phones.
- **Unparseable `updated` values** raise a `ValueError` rather than being silently guessed. It's better to find a bad date before the send than after.

